  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["U1"],
      "pins": ["U1.18", "U1.19", "U1.20", "U1.21", "U1.22", "U1.24"],
      "nets": ["CS0", "SCK", "CS1", "CS2", "GPIO3", "GPIO4", "GPIO5", "GPIO6", "GPIO7", "GPIO9"],
      "observed": "On the MCU sheet the SPI/CS net labels are attached to the wrong ESP32-C3 GPIOs: the label CS0 sits on the GPIO3/ADC1_CH3 pin (pin 18), SCK on the GPIO4/ADC1_CH4 pin (pin 19), CS1 on the GPIO5/ADC2_CH0 pin (pin 20), CS2 on the GPIO6 pin (pin 21), and a second SCK label on the GPIO9 pin (pin 24). The GPIO7 pin (pin 22) carries no net label. Only SO on GPIO10 matches the spec.",
      "expected": "The specification states the thermocouple SPI is wired to GPIO5=SCK, GPIO10=SO, with independent chip-selects CS0=GPIO4, CS1=GPIO6, CS2=GPIO7 (confirmed by firmware SPI2 on GPIO5/GPIO10 and CS pins GPIO4/6/7). GPIO3 should not carry CS0, GPIO4 should not carry SCK, GPIO7 should carry CS2, and SCK must not be duplicated on GPIO9.",
      "evidence": [
        {"source": "schematic", "quote": "mcu.kicad_sch: U1 right-side pins show net-label boxes CS0@GPIO3/ADC1_CH3, SCK@GPIO4/ADC1_CH4, CS1@GPIO5/ADC2_CH0, CS2@GPIO6, SCK@GPIO9, SO@GPIO10; GPIO7 pin has no label."},
        {"source": "spec", "quote": "SCK on GPIO5 and miso on GPIO10; three independent CS Output pins on GPIO4/GPIO6/GPIO7 ... ~{CS} on U2/U3/U4 goes to separate nets CS0/CS1/CS2, driven by ESP32 GPIO4/GPIO6/GPIO7 respectively."}
      ],
      "impact": "The firmware drives SCK on GPIO5 and CS0/CS1/CS2 on GPIO4/6/7, but the board routes those nets to GPIO4/3/5/6 and additionally shorts SCK to GPIO9. None of the three MAX31855 thermocouple interfaces is clocked or selected on the GPIO the firmware expects, so all thermocouple reads fail and the heater control loop cannot obtain temperature (the controller would trip a thermocouple fault / be unable to regulate).",
      "confidence": 0.55
    }
  ],
  "summary": "The power, heater-switch, buck-regulator and thermocouple-channel wiring match the specification, but on the MCU sheet the SPI/CS net labels are assigned to the wrong ESP32-C3 GPIOs (CS0 on GPIO3, SCK on GPIO4 and again on GPIO9, CS1 on GPIO5, CS2 on GPIO6, GPIO7 unused) instead of the spec's GPIO4=CS0, GPIO5=SCK, GPIO6=CS1, GPIO7=CS2, so the thermocouple SPI bus is mis-routed."
}

